def find_first_bad(data, ok):
    lo, hi = 0, len(data)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(data[:mid + 1]):
            lo = mid + 1
        else:
            hi = mid
    return lo

readings = [3, 4, 5, 6, 7, 8, "N/A", 9, 10]                  # one bad entry hides in the data
print(find_first_bad(readings, lambda part: all(isinstance(x, (int, float)) for x in part)))   # index 6

