from collections import OrderedDict

class LRU:
    def __init__(self, size):
        self.size, self.items, self.hits, self.misses = size, OrderedDict(), 0, 0
    def get(self, key, load):
        if key in self.items:
            self.items.move_to_end(key); self.hits += 1
            return self.items[key]
        self.misses += 1
        self.items[key] = load(key)                       # the slow source
        if len(self.items) > self.size:
            self.items.popitem(last=False)               # evict the least recently used
        return self.items[key]

cache = LRU(3)
for key in "ABABCADAEBA":
    cache.get(key, load=lambda k: k.lower())
print("hits", cache.hits, "misses", cache.misses)

